/**
 * AI Service - Qwen API Integration
 * Provides AI capabilities for Sudoku: Hint, Tutor, Solve, Explain
 */

import { writable, get } from 'svelte/store';
import { AI_CONFIG, SUDOKU_TUTOR_PROMPT } from './config.js';
import { apiKey } from '@sudoku/stores/settings';

// AI Service State
export const aiLoading = writable(false);
export const aiError = writable(null);
export const aiResponse = writable(null);

/**
 * Convert Sudoku grid to text representation
 * @param {number[][]} grid - 9x9 Sudoku grid
 */
function gridToText(grid) {
  let text = 'Current Sudoku board:\n';
  for (let y = 0; y < 9; y++) {
    let row = '';
    for (let x = 0; x < 9; x++) {
      row += grid[y][x] === 0 ? '.' : grid[y][x];
      if (x === 2 || x === 5) row += ' ';
    }
    text += row + '\n';
    if (y === 2 || y === 5) text += '\n';
  }
  return text;
}

/**
 * Call Qwen/DashScope API
 * @param {string} userMessage - User message content
 * @param {string} systemPrompt - Optional system prompt override
 */
async function callQwenAPI(userMessage, systemPrompt = SUDOKU_TUTOR_PROMPT) {
  const key = get(apiKey) || localStorage.getItem('ai_api_key');

  if (!key) {
    throw new Error('请先在侧边栏配置您的千问 API Key');
  }

  const response = await fetch(AI_CONFIG.apiUrl, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${key}`,
    },
    body: JSON.stringify({
      model: AI_CONFIG.model,
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userMessage },
      ],
      temperature: AI_CONFIG.temperature,
      max_tokens: AI_CONFIG.maxTokens,
    }),
  });

  if (!response.ok) {
    const errorData = await response.json().catch(() => ({}));
    throw new Error(`API error: ${response.status} - ${errorData.error?.message || response.statusText}`);
  }

  const data = await response.json();
  return data.choices?.[0]?.message?.content || '';
}

/**
 * Build prompt for Hint capability
 */
function buildHintPrompt(grid, userGrid) {
  const boardText = gridToText(grid);
  const userBoardText = gridToText(userGrid);

  return `I need a hint for this Sudoku puzzle.

${boardText}

Current player progress (user filled cells shown as numbers, original clues unchanged):
${userBoardText}

Please provide a STRATEGIC HINT only:
1. Identify ONE cell that can be solved or has a high probability of being solvable
2. Explain WHAT strategy to use (e.g., "naked pair", "hidden single", "pointing pair")
3. Explain WHY this strategy applies here
4. Do NOT give the final answer

Format your hint like this:
🎯 Cell: (row, col) - e.g., (3, 5)
💡 Strategy: [strategy name]
📖 Why: [explanation of why this strategy applies]
❌ Don't say: "The answer is X"`;
}

/**
 * Build prompt for Tutor capability
 */
function buildTutorPrompt(question, grid, userGrid) {
  const boardText = gridToText(grid);
  const userBoardText = gridToText(userGrid);

  return `Current Sudoku board state:
${boardText}

Player's current progress:
${userBoardText}

Player's question: ${question}

As a tutor, help them understand Sudoku better by:
1. Breaking down the concept they don't understand
2. Using examples from their current board
3. Being encouraging and patient
4. Leading them to understand, not giving direct answers`;
}

/**
 * Build prompt for Solve capability
 */
function buildSolvePrompt(grid, userGrid) {
  const boardText = gridToText(grid);
  const userBoardText = gridToText(userGrid);

  return `Help me solve this Sudoku step by step.

${boardText}

Player's current progress (only filled cells shown):
${userBoardText}

Please provide the solution IN THE SAME FORMAT with all empty cells filled:
Show the complete solved board. Also explain the key steps/strategies used.

Format:
📋 Solution:
[show solved board in same format]

🔑 Key strategies used:
[brief explanation]`;
}

/**
 * Build prompt for Explain capability
 */
function buildExplainPrompt(grid, userGrid, focusCell = null) {
  const boardText = gridToText(grid);
  const userBoardText = gridToText(userGrid);

  let focusPart = focusCell
    ? `Please focus on explaining the logic around cell (${focusCell.row + 1}, ${focusCell.col + 1})`
    : 'Give a brief overview of the board strategies at play';

  return `Analyze this Sudoku board and provide insights.

${boardText}

Player's current progress:
${userBoardText}

${focusPart}

Provide a clear explanation of:
1. What patterns/strategies are visible
2. How to approach solving this puzzle
3. Key decisions the player should consider`;
}

// AI Capabilities
export const ai = {
  /**
   * Get AI Hint - Strategic hint for next move
   */
  async getHint(grid, userGrid) {
    aiLoading.set(true);
    aiError.set(null);
    aiResponse.set(null);

    try {
      const prompt = buildHintPrompt(grid, userGrid);
      const response = await callQwenAPI(prompt);
      aiResponse.set({ type: 'hint', content: response });
      return response;
    } catch (err) {
      aiError.set(err.message);
      throw err;
    } finally {
      aiLoading.set(false);
    }
  },

  /**
   * Get AI Tutor response
   */
  async getTutor(question, grid, userGrid) {
    aiLoading.set(true);
    aiError.set(null);
    aiResponse.set(null);

    try {
      const prompt = buildTutorPrompt(question, grid, userGrid);
      const response = await callQwenAPI(prompt);
      aiResponse.set({ type: 'tutor', content: response });
      return response;
    } catch (err) {
      aiError.set(err.message);
      throw err;
    } finally {
      aiLoading.set(false);
    }
  },

  /**
   * Get AI Solve - Step by step solution
   */
  async getSolve(grid, userGrid) {
    aiLoading.set(true);
    aiError.set(null);
    aiResponse.set(null);

    try {
      const prompt = buildSolvePrompt(grid, userGrid);
      const response = await callQwenAPI(prompt);
      aiResponse.set({ type: 'solve', content: response });
      return response;
    } catch (err) {
      aiError.set(err.message);
      throw err;
    } finally {
      aiLoading.set(false);
    }
  },

  /**
   * Get AI Explain - Board analysis
   */
  async getExplain(grid, userGrid, focusCell = null) {
    aiLoading.set(true);
    aiError.set(null);
    aiResponse.set(null);

    try {
      const prompt = buildExplainPrompt(grid, userGrid, focusCell);
      const response = await callQwenAPI(prompt);
      aiResponse.set({ type: 'explain', content: response });
      return response;
    } catch (err) {
      aiError.set(err.message);
      throw err;
    } finally {
      aiLoading.set(false);
    }
  },

  /**
   * Clear AI response
   */
  clearResponse() {
    aiResponse.set(null);
    aiError.set(null);
  },
};

export default ai;